    'Customer wallet must be on for customers to receive rewards.' => 'يجب أن تكون محفظة العميل قيد التشغيل حتى يتمكن العملاء من الحصول على المكافآت.',
    'Customer wallets' => 'محافظ العملاء',
    'Customer will get discount on first order' => 'سيحصل العميل على خصم على الطلب الأول',
    'Customers' => 'العملاء',
    'Customers can add funds to the wallet with an available payment method.' => 'وبتمكين هذا الخيار، سيتمكن العملاء من إضافة أموال إلى المحفظة من خلال طريقة الدفع المتاحة',
    'Customers can browse and search products by brand inside any shop.' => 'إذا تم تمكينه، فيمكن للعملاء رؤية العلامات التجارية ويمكنهم تصفح المنتجات من كل علامة تجارية والبحث عنها داخل أي متجر.',
    'Customers can check out without creating or logging into an account.' => 'يمكن للعملاء تسجيل الخروج دون إنشاء حساب أو تسجيل الدخول إليه.',
    'Customers can enter their billing address.' => 'يمكن للعملاء إدخال عنوان إرسال الفواتير الخاص بهم.',
    'Customers can pay for orders from their wallet balance.' => 'عند تمكين ميزة المحفظة، يمكن للعملاء استخدام رصيد محفظتهم لدفع ثمن الطلبات.',
    'Customers cannot add money to their wallet.' => 'إذا لم يتمكن العملاء المعاقين من إضافة أموال إلى محفظتهم',
    'Customers choose from these, so add the relevant input fields.' => 'التي سيختار منها العملاء ويضيفون حقول الإدخال ذات الصلة لطريقة الدفع',
    'Customers earn loyalty points on each order.' => 'إذا تم تمكين خيار نقطة الولاء، فسيكون متاحًا للعملاء لكل طلب عند تقديم الطلب',
    'Customers earn rewards when someone registers with their referral code.' => 'إذا تم تمكينه، فسيحصل العملاء على مكافآت عندما يقوم شخص ما بالتسجيل باستخدام رمز الإحالة الخاص بهم.',
    'Customers get a code. The delivery man collects it on delivery.' => 'يحصل العملاء على رمز. يقوم رجل التوصيل باستلامها عند التسليم.',
    'Customers get a wallet for placing orders and receiving refunds.' => 'إذا تم تمكين العملاء، فيمكنهم الحصول على خيار المحفظة في حساباتهم واستخدامها أثناء تقديم الطلبات واسترداد المبالغ المستردة',
    'Customers get refunds in the wallet and can pay orders with it.' => 'يحصل العملاء على المبالغ المستردة في المحفظة ويمكنهم دفع الطلبات بها.',
    'Customers must reach this amount before they can check out.' => ' وهذا يعني أن العملاء سيحتاجون إلى إضافة عناصر كافية للوصول إلى هذا المبلغ المحدد قبل أن يتمكنوا من متابعة عملية الدفع.',
    'Customers must verify their email during sign-up.' => 'إذا كان التحقق من البريد الإلكتروني قيد التشغيل، فيجب على العملاء التحقق من بريدهم الإلكتروني أثناء التسجيل لضمان عملية تسجيل دخول آمنة.',
    'Customers must verify their phone with an OTP to sign up.' => 'إذا كان التحقق من رقم الهاتف قيد التشغيل، فيجب على العملاء التحقق من رقم هاتفهم باستخدام كلمة مرور لمرة واحدة لإكمال عملية التسجيل.',
    'Customers pay and instantly download pre-uploaded digital products.' => 'بالنسبة لعمليات تسليم المنتجات الجاهزة، يمكن للعملاء الدفع وتنزيل المنتجات الرقمية التي تم تحميلها مسبقًا على الفور.',
    'Customers pay by wallet, card or internet banking before shipping.' => 'Customers pay by wallet, card or internet banking before shipping.',
    'Customers pay first, then admin uploads the digital products for download.' => 'بالنسبة لعمليات التسليم الجاهزة بعد البيع، يدفع العملاء أولاً ثم يقوم المسؤول بتحميل المنتجات الرقمية التي تصبح متاحة للعملاء للتنزيل',
    'Customers pay first, then the vendor uploads the digital products for download.' => 'بالنسبة لعمليات التسليم الجاهزة بعد البيع، يدفع العملاء أولاً ثم يقوم البائع بتحميل المنتجات الرقمية التي تصبح متاحة للعملاء للتنزيل',
    'Customers pay online by wallet, card or internet banking at checkout.' => 'يتيح الدفع الرقمي للعملاء الدفع عبر الإنترنت مقابل طلباتهم باستخدام طرق مثل محافظ الهاتف المحمول، على سبيل المثال بطاقات الخصم الائتمانية (بكاش ونجاد والصواريخ) أو الخدمات المصرفية عبر الإنترنت المدمجة داخل النظام عند تقديم الطلب.',
    'Customers recover accounts with a code sent by email or phone.' => 'Customers recover accounts with a code sent by email or phone.',
    'Customers refer friends with a code and earn rewards.' => 'السماح للعملاء بإحالة عملك إلى الأصدقاء والعائلة باستخدام رمز الإحالة وكسب المكافآت.',
    'Customers sign in with Apple credentials, on Apple devices only.' => 'تمكين تسجيل الدخول إلى Apple، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد تسجيل الدخول إلى Apple الحالية لأجهزة Apple فقط',
    'Customers sign in with a phone number and OTP, not a password.' => 'Customers sign in with a phone number and OTP, not a password.',
    'Customers sign in with a social media account.' => 'من خلال تسجيل الدخول عبر وسائل التواصل الاجتماعي، يمكن للعملاء تسجيل الدخول باستخدام حسابات الوسائط الاجتماعية لتمكين هذه الميزة',
