    'Showing the brand tells customers who makes the item.' => 'إن عرض اسم العلامة التجارية على صفحات منتجك يساعد العملاء على معرفة من يصنع المنتج.',
    'Shown above the footer. One banner only. Max 2 MB, ratio 4:1.' => 'يظهر هذا الشعار في أسفل الصفحة الرئيسية قبل قسم التذييل لجذب الانتباه عند التصفح إلى قسم التذييل وعرض العروض أو العروض الترويجية. يمكنك إضافة شعار واحد فقط. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 4:1.',
    'Shown as a separate line on bills, invoices and order summaries.' => 'تظهر ضريبة القيمة المضافة/الضريبة كبند مميز في الفواتير والفواتير وملخصات الطلبات.',
    'Shown as the sender on the shipping label.' => 'يظهر كمرسل على ملصق الشحن.',
