    'Shown in the auction category section on the website.' => 'تظهر في قسم فئة المزاد على الموقع.',
    'Shown in the header nav bar. Max 2 MB, ratio 4:1.' => 'يظهر هذا الشعار في قسم شريط التنقل في الرأس لعرض العروض القصيرة والفعالة. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 4:1.',
    'Shown on site entry. One banner only. Max 2 MB, ratio 1:1.' => 'يظهر الشعار المنبثق عندما يزور المستخدم موقع الويب. إنها لافتة من نوع واحد محدد. يمكنك تفعيل لافتة واحدة فقط في كل مرة. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجا بايت وأن نسبة الصورة 1:1.',
    'Shown to the driver at pickup.' => 'تظهر للسائق عند البيك اب.',
    'Shows AI features in admin, vendor panel and app.' => 'سيؤدي تمكين هذا إلى تنشيط ميزات الذكاء الاصطناعي في المسؤول ولوحة البائع وتطبيق البائع',
    'Shows Customer Wallet as a refund method on the Admin Refund page.' => 'في حالة تمكينها، ستظهر طريقة الدفع بمحفظة العميل في صفحة استرداد المبلغ الإداري عند معالجة المبالغ المستردة للطلب.',
    'Shows POS in the vendor panel and app.' => 'في حالة تمكين خيار نقطة البيع، سيكون متاحًا على لوحة البائع وتطبيق البائع',
    'Shows customers what their points are worth in wallet money.' => 'فهو يساعد العملاء على فهم قيمة نقاطهم عندما يريدون تحويلها إلى أموال المحفظة.',
