    'Shows customers who ordered within this date range' => 'يعرض العملاء الذين طلبوا خلال هذا النطاق الزمني',
    'Shows customers who placed orders in this business module' => 'يُظهر العملاء الذين قدموا طلبات في وحدة الأعمال هذه',
    'Shows each method required fields, who it applies to, and its status.' => 'لكل طريقة يمكنك رؤية الحقول المطلوبة، ومن تنطبق عليه، وحالتها الافتراضية والنشطة.',
    'Shows how data is organised across the database.' => 'يوضح هذا القسم كيفية تنظيم البيانات عبر أجزاء مختلفة من قاعدة البيانات.',
    'Shows if the request is' => 'يظهر إذا كان الطلب',
    'Shows store availability, creation date and other details.' => 'يعرض قسم تفاصيل المتجر هذا معلومات أساسية عن متاجرك، مثل توفرها الحالي وتاريخ إنشائها والتفاصيل الأخرى ذات الصلة.',
    'Shows the AI shopping assistant icon on the storefront.' => 'Shows the AI shopping assistant icon on the storefront.',
    'Shows the AI shopping assistant icon to customers.' => 'Shows the AI shopping assistant icon to customers.',
    'Shows the App Store button in the website footer.' => 'إذا تم تمكينه، فيمكن للجميع رؤية زر App Store في تذييل موقع الويب',
    'Shows the App Store download button in the footer.' => 'إذا تم تمكينه، فسيكون زر التنزيل من متجر التطبيقات مرئيًا في قسم التذييل',
    'Shows the Google Play button in the website footer.' => 'إذا تم تمكينه، فيمكن للجميع رؤية زر متجر Google Play في تذييل موقع الويب',
    'Shows the blog section on the website.' => 'سيؤدي تفعيل هذا الخيار إلى جعل قسم المدونة مرئيًا على موقع الويب للمشاهدين',
    'Shows the payment account details and what the customer must provide.' => 'ستجد لكل طريقة معلومات حساب الدفع وتفاصيل عما يجب على العميل تقديمه أثناء الدفع.',
    'Shows the product in the clearance section on the app and website.' => 'إضافة عرض المنتج في قسم عرض التخليص في تطبيق العميل والموقع الإلكتروني',
    'Shows the translated values for the selected language against the default.' => 'في هذه الصفحة، يمكنك رؤية القيم المترجمة للغة المحددة بناءً على اللغة الافتراضية الحالية.',
    'Shows this FAQ in the app and website.' => 'إذا قمت بتمكين هذه الأسئلة الشائعة، فسيتم عرضها في تطبيق المستخدم وموقع الويب',
    'Shows this FAQ on the website and app.' => 'يعرض هذه الأسئلة الشائعة على الموقع والتطبيق.',
    'Shows this banner on the website and app.' => 'إذا تم تمكين هذا الشعار، فسيكون متاحًا على موقع الويب وتطبيق العميل',
