    'Shows this deal of the day on the website and app. Only one deal runs at a time, so the deal running now will be turned off.' => 'يعرض صفقة اليوم هذه على الموقع الإلكتروني والتطبيق. يتم تنفيذ صفقة واحدة فقط في كل مرة، وبالتالي سيتم إيقاف الصفقة الجارية الآن.',
    'Shows this featured deal on the website and app.' => 'إذا تم تمكين هذه الصفقة المميزة، فستكون متاحة على الموقع الإلكتروني وتطبيق العميل',
