    'Shows this product on the website and app.' => 'إذا تم تمكينه، فسيكون هذا المنتج متاحًا على موقع الويب وتطبيق العميل',
    'Shows this review on the website and app.' => 'إذا تم تمكينه، فيمكن لأي شخص رؤية هذه المراجعة على موقع المستخدم وتطبيق العميل',
    'Shows this section on the vendor registration page.' => 'عند تشغيل الحالة، سيظهر هذا القسم في صفحة تسجيل البائع',
    'Shows this shipping method at checkout in the app and website.' => 'إذا قمت بتمكين طريقة الشحن هذه، فسيتم عرضها في تطبيق المستخدم والموقع الإلكتروني لتسجيل خروج العميل',
    'Shows your current terms and conditions on completed invoices.' => 'أبقِ عملائك على علم بالشروط والأحكام الحالية من خلال إظهارها على الفواتير المكتملة من خلال هذه الإعدادات.',
